def triage_route(h, method, p, raw):
    """Settings › Session triage (GET / PUT /api/v1/agents/triage); True when it answered."""
    if p != "/api/v1/agents/triage":
        return False
    if method == "PUT":
        body = json.loads(raw or b"{}")
