def file_read(path, cwd, offset, stream=False):
    p = file_path(path, cwd)
    kind = file_kind(p) if p else "missing"
    if kind == "missing":
        return None
    name = os.path.basename(p.rstrip("/"))
    if kind == "dir":
        prefix = p.rstrip("/") + "/"
        names = sorted({f[len(prefix):].split("/")[0] + ("/" if "/" in f[len(prefix):] else "") for f in FILES if f.startswith(prefix)})
        return {"path": p, "name": name, "size": 0, "is_dir": True, "entries": names, "truncated": False}
    value = FILES[p]
    if isinstance(value, bytes):
        if stream:  # file?stream=1 (docs/protocol/protocol.md "File preview"): described, the bytes from …/file/download
            return {"path": p, "name": name, "size": len(value), "mime": mock_mime(p), "stream": True, "revision": "%x-1" % len(value),
                    "truncated": False, "is_dir": False}
        return {"path": p, "name": name, "size": len(value), "mime": mock_mime(p), "data": base64.b64encode(value[:FILE_PAGE]).decode(),
                "truncated": len(value) > FILE_PAGE, "is_dir": False}
    data = value.encode()
    page = data[offset:offset + FILE_PAGE]
    more = offset + len(page) < len(data)
    if more:
        page = page[:page.rfind(b"\n") + 1]
    ext = os.path.splitext(name)[1].lower()
    mime = {".json": "application/json", ".md": "text/markdown", ".csv": "text/csv"}.get(ext, "text/plain; charset=utf-8")
    return {"path": p, "name": name, "size": len(data), "mime": mime, "text": page.decode(), "truncated": more,
            "is_dir": False, "offset": offset, "next": offset + len(page) if more else 0}


# ---------- personas (docs/apple/persona.md) ----------
# MOCK_PERSONAS=<dir>: the packages in it, as the hub lists and serves ~/.persona/personas. MOCK_PERSONAS=demo: the
# original placeholder (scripts/assets/make_persona.py demo), made into a temporary directory at start. With "builtin"
# among them (MOCK_PERSONAS=builtin, demo,builtin): the packages built into personad too (server/internal/hub/personas,
# the frog look), first, as the hub lists them. A tiered one shows MOCK_PERSONA_TIER (default: its default tier); GET
# /mock/persona-tier?tier=<key> moves it and pushes "personas", as the hub does when the board moves the user.
_PERSONA_ARGS = [x for x in os.environ.get("MOCK_PERSONAS", "").split(",") if x]
BUILTIN_PERSONAS = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "server", "internal", "hub", "personas")
PERSONA_ROOTS = []  # directories of packages, the built-in one first
if "builtin" in _PERSONA_ARGS:
    PERSONA_ROOTS.append(os.path.realpath(BUILTIN_PERSONAS))
for arg in _PERSONA_ARGS:
    if arg == "demo":
        import subprocess, tempfile
        d = tempfile.mkdtemp(prefix="mock-personas-")
        subprocess.run([sys.executable, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "assets", "make_persona.py"),
                        "demo", "--out", d], check=True, stdout=sys.stderr)
        PERSONA_ROOTS.append(d)
    elif arg != "builtin":
        PERSONA_ROOTS.append(arg)
PERSONA_TIER = {"tier": os.environ.get("MOCK_PERSONA_TIER", "")}


def _persona_files(root):
    return sorted(os.path.relpath(os.path.join(r, f), root) for r, ds, fs in os.walk(root) for f in fs
                  if not f.startswith(".") and not any(x.startswith(".") for x in os.path.relpath(r, root).split(os.sep) if x != "."))


def _persona_rev(root, files, salt=b""):
    h, total = hashlib.sha256(), 0
    h.update(salt)
    for f in sorted(files):
        b = open(os.path.join(root, f), "rb").read()
        h.update(("%s\0%d\0" % (f, len(b))).encode()); h.update(b)
        total += len(b)
    return h.hexdigest()[:16], total


def personas():
    out, seen = [], set()
    for base in PERSONA_ROOTS:
        if not os.path.isdir(base):
            continue
        for pid in sorted(os.listdir(base)):
            root = os.path.join(base, pid)
            mpath = os.path.join(root, "persona.json")
            if pid == "persona" or pid in RETIRED_LOOK_IDS or pid.startswith(".") or pid in seen or not os.path.isfile(mpath):
                continue
            seen.add(pid)
            m = json.load(open(mpath))
            tiers = m.get("tiers")
            if not tiers:
                rev, total = _persona_rev(root, _persona_files(root))
                out.append({"id": pid, "rev": rev, "bytes": total, "manifest": m})
                continue
            levels = {t["key"]: t for t in tiers["levels"]}
            key = PERSONA_TIER["tier"] if PERSONA_TIER["tier"] in levels else tiers["default"]
            raw = open(os.path.join(root, levels[key]["manifest"]), "rb").read()
            tm = json.loads(raw)
            named = sorted(set(tm["avatar"]["sizes"].values()) | {st["file"] for st in tm["dot"]["states"].values()})
            rev, total = _persona_rev(root, named, ("tier:%s\0" % key).encode() + raw)
            out.append({"id": pid, "rev": rev, "bytes": total + len(raw), "manifest": tm})
    return out


def persona_file(rest):
    """<id>/<file> inside its package, or None."""
    pid, _, f = rest.partition("/")
    if pid == "persona" or pid in RETIRED_LOOK_IDS:
        return None
    ext = _ext_looks().get(pid)
    if ext:
        return os.path.join(LOOKS_ROOT, f) if f in ext[1] else None
    for base in PERSONA_ROOTS:
        root = os.path.realpath(os.path.join(base, pid))
        p = os.path.realpath(os.path.join(root, f))
        if p.startswith(root + os.sep) and os.path.isfile(p) and not os.path.basename(p).startswith("."):
            return p
    return None


def set_persona_tier(key):
    """Moves the tiered looks to that tier and tells every app, as the hub does (persona_tiers.go)."""
    PERSONA_TIER["tier"] = key
    for send, _ in list(LIVE):
        try:
            send({"type": "personas"})
        except Exception:
            pass


# ---------- looks (docs/extensions/extensions.md "Persona look", #3200) ----------
# MOCK_LOOKS=example (or a package directory): an extension's looks (schema/extension/examples/example-looks), listed
# and served as the hub does (a made persona.json; only the files a look names). GET /api/v1/looks lists the built-in
# looks, the packages and these; PUT /api/v1/looks/current chooses one (MOCK_LOOK: chosen at start) and pushes "look".
_LOOKS_ARG = os.environ.get("MOCK_LOOKS", "")
LOOKS_ROOT = (os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "schema", "extension", "examples", "example-looks")
              if _LOOKS_ARG == "example" else _LOOKS_ARG)
LOOK_CHOICE = {"id": os.environ.get("MOCK_LOOK") or None, "updated_at": "2026-11-05T12:00:00Z"}
BUILTIN_LOOKS = [("persona", "团子", {"en": "Mochi", "ja": "だんご"})]
RETIRED_LOOK_IDS = {"persona-visor", "persona-circuit", "persona-pixel", "persona-facet", "persona-blob"}


def _ext_looks():
    """id → (manifest, files, extension id, extension name, app_icon_fallback) of MOCK_LOOKS's looks."""
    if not LOOKS_ROOT or not os.path.isfile(os.path.join(LOOKS_ROOT, "persona-extension.json")):
        return {}
    ext = json.load(open(os.path.join(LOOKS_ROOT, "persona-extension.json")))
    out = {}
    for l in ext.get("contributes", {}).get("looks", []):
        if l["id"] in RETIRED_LOOK_IDS or l["id"] in {"persona", "nwverse"}:
            continue
        av = l["avatar"]
        files = sorted(set(av["sizes"].values()) | ({av["svg"]} if av.get("svg") else set())
                       | set((av.get("dark") or {}).get("sizes", {}).values())
                       | ({av["dark"]["svg"]} if (av.get("dark") or {}).get("svg") else set())
                       | {st["file"] for st in (l.get("dot") or {}).get("states", {}).values()})
        dot = l.get("dot")
        if not dot:
            side = max(av["sizes"], key=int)
            dot = {"size": int(side), "states": {"idle": {"file": av["sizes"][side]}}}
        m = {"format": 1, "id": l["id"], "name": l["name"], "avatar": av, "dot": dot, "app_icon_fallback": l["app_icon_fallback"],
             "source": {"kind": "extension", "extension": ext["id"], "extension_name": ext["name"]}}
        for k in ("subtitle", "names", "subtitles", "colors"):
            if k in l:
                m[k] = l[k]
        out[l["id"]] = (m, files, ext["id"], ext["name"], l["app_icon_fallback"])
    return out


def ext_look_personas():
    out = []
    for lid, (m, files, _, _, _) in _ext_looks().items():
        raw = json.dumps(m, sort_keys=True).encode()
        rev, total = _persona_rev(LOOKS_ROOT, files, raw)
        out.append({"id": lid, "rev": rev, "bytes": total + len(raw), "manifest": m})
    return out


def looks_list():
    out = [{"id": i, "source": "builtin", "name": n, "names": ns, "app_icon": i} for i, n, ns in BUILTIN_LOOKS]
    ext = _ext_looks()
    for p in personas() + ext_look_personas():
        m = p["manifest"]
        v = {"id": p["id"], "source": "hub", "name": m.get("name", ""), "app_icon": "persona", "rev": p["rev"], "bytes": p["bytes"], "manifest": m}
        for k in ("names", "subtitle", "subtitles"):
            if k in m:
                v[k] = m[k]
        if p["id"] in ext:
            _, _, eid, ename, icon = ext[p["id"]]
            v.update(source="extension", extension=eid, extension_name=ename, app_icon=icon)
        out.append(v)
    return out


def look_current(looks=None):
    looks = looks if looks is not None else looks_list()
    cid = LOOK_CHOICE["id"]
    eff = cid if cid and any(l["id"] == cid for l in looks) else "persona"
    cur = {"id": cid, "effective": eff}
    if cid:
        cur["updated_at"] = LOOK_CHOICE["updated_at"]
    return cur


def looks_route(handler, method, p, raw):
    if p == "/api/v1/looks" and method == "GET":
        looks = looks_list()
        handler.send_json({"looks": looks, "current": look_current(looks)})
        return True
    if p == "/api/v1/looks/current" and method == "PUT":
        body = json.loads(raw or b"{}")
        looks = looks_list()
        if body.get("if_unset") and LOOK_CHOICE["id"]:
            handler.send_json(look_current(looks))
            return True
        if not any(l["id"] == body.get("id") for l in looks):
            handler.send_json({"error": "no look %r" % body.get("id")}, 404)
            return True
        LOOK_CHOICE.update(id=body["id"], updated_at=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()))
        cur = look_current(looks)
        for send, _ in list(LIVE):
            try:
                send({"type": "look", "id": cur["id"], "effective": cur["effective"]})
            except Exception:
                pass
        handler.send_json(cur)
        return True
    return False


