# MOCK_COMPACT=1: compactions as Claude Code writes them, after the hub turned them into items: the Persona main
# conversation compacted while idle after its last answer (the boundary, the summary it went on from, the idle note);
# Review PR #42 compacted with /compact, then in the middle of a later turn (auto). For the chat's compaction divider.
if os.environ.get("MOCK_COMPACT"):
    def _compaction(ts, trigger, idle=False):
        b = it("system", "notice", ts, text="上下文已压缩")
        b["compact"] = {"trigger": trigger, "pre_tokens": 151467}
        out = [b, it("system", "notice", ts, text="已从压缩的上下文继续")]
        if idle:
            out.append(it("system", "notice", ts, text="Compacted while idle, before the prompt cache expired · turn off with "
                                                       "\"idleCompaction\": false in settings.json"))
        return out
    ITEMS[ASK1] = ITEMS[ASK1] + _compaction(1, "auto", idle=True)
    ITEMS[REVIEW] = ITEMS[REVIEW] + [it("user", "text", 40, text="/compact")] + _compaction(40, "manual") + [
        it("user", "text", 30, text="把命名的建议也改掉")] + tool("Read", {"file_path": "/Users/me/code/weather/Sources/Client.swift"}, "struct Client {}", 30) \
        + _compaction(29, "auto") + tool("Edit", {"file_path": "/Users/me/code/weather/Sources/Client.swift"}, "ok", 28) + [
        it("assistant", "text", 27, text="两处命名都改好了。")]
    for _sid in (ASK1, REVIEW):  # seq goes up through the conversation
        for _n, _x in enumerate(ITEMS[_sid]):
            _x["seq"] = ITEMS[_sid][0]["seq"] + _n


def assistant_run(sid, mid):
    """The running turn, in the rhythm of a real one (thinking, a call, its result; now and then a few words to the user
    streamed as deltas, then written, then more calls)."""
    import time
    steps = int(os.environ.get("MOCK_ASSISTANT_RUN_STEPS", "120"))
    # MOCK_ASSISTANT_RUN=flip: the session's transcript exists twice (two config dirs) and the pushes come from one
    # file, then the other: their `history` differs.
    flip = os.environ.get("MOCK_ASSISTANT_RUN") == "flip"
    pushed = [0]

    def send_all(msg):
        for out, subs in list(LIVE):
            try:
                if sid in subs:
                    out(msg)
            except Exception:
                pass

    def add(new):
        before = ITEMS[sid][-1]["seq"]
        for i, x in enumerate(new):
            x["seq"] = before + 1 + i
        ITEMS[sid] = ITEMS[sid] + new
        sp = span(new, before)
        pushed[0] += 1
        if flip and pushed[0] % 2:
            sp["history"] = HISTORY + "-other"
        send_all({"type": "items", "machine_id": mid, "session_id": sid, "items": new, **sp})
        now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
        ASSISTANT[0].update(rev=(ASSISTANT[0].get("rev") or 1000) + 1, updated_at=now)
        push_machine(mid)

    for n in range(12, 12 + steps):
        if n % 4 == 0:  # a few words to the user, streamed, then written; the next request clears the live copy
            words = "在核对第 %d 处要哪些凭据，以及这台机器上的服务能不能给出这些凭据，然后接着看下一处。" % n
            for k in range(1, 11):
                time.sleep(0.2)
                send_all({"type": "delta", "machine_id": mid, "session_id": sid, "text": words[:len(words) * k // 10]})
            time.sleep(0.6)
            add([it("assistant", "text", 0, text=words)])
            ASSISTANT[0]["last_text"] = words
            time.sleep(0.4)
            send_all({"type": "delta", "machine_id": mid, "session_id": sid, "text": ""})
        time.sleep(0.8)
        add([it("assistant", "thinking", 0, text="先看看第 %d 处。" % n)])
        time.sleep(0.4)
        use, res = assistant_run_call(n)
        add([use])
        ASSISTANT[0]["last_text"] = "Read example note %d on the hub machine" % n
        time.sleep(1.2)
        add([res])


def last_turns(items, n):
    """The last n turns of items (each from a user's message on) and whether anything is left before them."""
    starts = [i for i, x in enumerate(items) if x.get("role") == "user" and x.get("kind") == "text"]
    cut = starts[-n] if len(starts) >= n else 0
    return items[cut:], cut > 0


def span(items, frm=None, to=None):
    out = {"history": HISTORY_NOW["token"], "to_seq": to if to is not None else (items[-1]["seq"] if items else 0)}
    if frm is not None:
        out["from_seq"] = frm
    return out


# ---------- a bad network, on demand ----------
# MOCK_DELAY=<seconds>: every request and pong is that late (a weak network). At runtime, for UI tests:
#   GET /mock/delay?s=3   the same, from now on (0 turns it off)
#   GET /mock/down?s=8    the hub is gone for that long: open WebSockets drop, new connections are closed unanswered
NET = {"delay": float(os.environ.get("MOCK_DELAY", "0")), "down_until": 0.0}

# ---------- frames lost, doubled, late or out of order (#1073) ----------
# POST /mock/wire {"rules": [{"type": "items", "action": "drop" | "dup" | "delay" | "hold", "ms": 1500, "count": 1,
# "session": "<id>"}]} adds rules: each takes the next `count` frames of that type (for that session, when given) going
# to any app and drops it, sends it twice, sends it `ms` later, or keeps it until POST /mock/wire/release
# {"order": "held" | "reverse", "clear": true} sends what was kept (and, with clear, drops the rules no frame took yet).
# GET /mock/wire: the rules left and what they did; /mock/reset clears both. Every socket's frames go through it, as
# they go out: a delta app's session list is already its delta and recorded as sent, as the hub records it when it
# queues the frame. A short outage is /mock/down.
WIRE = {"rules": [], "held": [], "log": []}
WIRE_LOCK = threading.Lock()
WIRE_ACTIONS = ("drop", "dup", "delay", "hold")


def wire_rule(obj):
    """The rule that takes this frame (its count goes down), or None."""
    typ = obj.get("type")
    sid = obj.get("session_id") or (obj.get("interaction") or {}).get("session_id")
    with WIRE_LOCK:
        for r in WIRE["rules"]:
            if r["type"] == typ and (not r.get("session") or r["session"] == sid):
                r["count"] -= 1
                if r["count"] <= 0:
                    WIRE["rules"].remove(r)
                WIRE["log"].append({"type": typ, "action": r["action"], "session": sid})
                return r
    return None


def wire_set(body):
    rules = body.get("rules") if isinstance(body, dict) else None
    if not isinstance(rules, list) or not rules:
        raise ValueError("rules: a list of {type, action, ms?, count?, session?}")
    out = []
    for r in rules:
        if not isinstance(r, dict) or not isinstance(r.get("type"), str) or r.get("action") not in WIRE_ACTIONS:
            raise ValueError("each rule needs a type and an action (%s)" % ", ".join(WIRE_ACTIONS))
        out.append({"type": r["type"], "action": r["action"], "ms": int(r.get("ms") or 1000), "count": int(r.get("count") or 1),
                    **({"session": r["session"]} if r.get("session") else {})})
    with WIRE_LOCK:
        WIRE["rules"].extend(out)
        return {"rules": list(WIRE["rules"]), "held": len(WIRE["held"])}


def wire_release(order, clear=False):
    with WIRE_LOCK:
        held, WIRE["held"] = WIRE["held"], []
        if clear:
            WIRE["rules"] = []
    if order == "reverse":
        held.reverse()
    for deliver, obj in held:
        try: deliver(obj)
        except OSError: pass  # that socket went meanwhile: lost with it
    return {"released": len(held)}


def wire_state():
    with WIRE_LOCK:
        return {"rules": list(WIRE["rules"]), "held": [obj.get("type") for _, obj in WIRE["held"]], "log": list(WIRE["log"])}


def wire_reset():
    with WIRE_LOCK:
        WIRE.update(rules=[], held=[], log=[])
