def mock_home(mid):
    return next((m.get("home") for m in MACHINES if m["id"] == mid), None) or "/home/me"


def mock_abs(mid, path, cwd):
    home = mock_home(mid)
    path = (path or "").strip() or (cwd or "")
    if path == "~" or path.startswith("~/"): path = home + path[1:]
    elif not path.startswith("/") and cwd: path = cwd.rstrip("/") + "/" + path
    return home, "/" + "/".join(x for x in path.split("/") if x and x != ".")


def mock_rel(home, path):
    """The tree key of an absolute path (dirs end with /), or None outside the tree."""
    if path == home: return ""
    if not path.startswith(home + "/"): return None
    rel = path[len(home) + 1:]
    return rel + "/" if rel + "/" in MOCK_TREE else rel if rel in MOCK_TREE else None


def mock_children(rel):
    out = []
    for k in MOCK_TREE:
        if k.startswith(rel) and k != rel:
            rest = k[len(rel):]
            if rest.count("/") == 0 or (rest.count("/") == 1 and rest.endswith("/")): out.append(k)
    return sorted(out, key=lambda k: (not k.endswith("/"), k.lower()))


def mock_size(v):
    return 0 if v is None else len(base64.b64decode(v[1])) if isinstance(v, tuple) else len(v.encode())


GIT_PULL_STATE = {"behind": 28, "mode": "success", "pulls": 0}
# MOCK_PERSONAL_AGENTS=1 (#138): a few personal agent conversations, and Remove from list (POST …/hide, …/unhide,
# GET /agents/hidden) kept in memory as the extension manager keeps it; GET /mock/personal-agents?reset=1 brings every one
# back. Off: none, as on a hub without the Lark extension.
PERSONAL_AGENTS = os.environ.get("MOCK_PERSONAL_AGENTS")
PERSONAL_HIDDEN = {}  # session id -> when (ms)
# #1368: GET /mock/start-fail?n=<count>&code=<code>&delay=<seconds>: the next n starts of an assistant conversation
# (POST /api/v1/assistant/conversations) answer 502 with that code (default assistant_in_doubt, delivered unknown), and
# every start, failed or not, first takes `delay` seconds (to see a retry spin). n=0&delay=0 puts it back.
START_FAIL = {"n": 0, "code": "assistant_in_doubt", "delay": 0.0}
def personal_rows():
    now = int(time.time() * 1000)
    rows = [("muse", "周报助手", 0.1, 2), ("grok_bot", "旅行规划", 1.5, 0), ("cue", "读书笔记", 5, 1), ("muse", "代码评审", 30, 0),
            ("grok_bot", "健身记录", 80, 0), ("cue", "菜谱整理", 200, 0)]
    return [{"id": "lark-bridge:%s:%d" % (prov, i), "source": "lark-bridge", "sessionKey": "%s:%d" % (prov, i), "provider": prov,
             "title": title, "canSend": True, "unreadCount": unread, "rankTimeMs": now - int(hours * 3600 * 1000), "hasAvatar": False}
            for i, (prov, title, hours, unread) in enumerate(rows)]
def personal_listed(hidden):
    return [r for r in personal_rows() if (r["id"] in PERSONAL_HIDDEN) == hidden] if PERSONAL_AGENTS else []
# MOCK_GIT_WRITE=1 (#6121): the Git panel's writes on a made-up repository that changes as they are made. GET
# /mock/git-write?fail=<code>[&files=a,b] makes the next write refuse with that code (git_conflict lists the files);
# ?reset=1 starts over; ?gone=1 puts the branch on an upstream deleted on the remote (#1884). The branch's pull request: ?pr=none|review|ready|auto sets it, ?pr_fail=no_gh|not_signed_in makes
# reading it refuse; POST git/pr opens one, git/pr/merge merges it or sets it to merge when ready.
def git_write_fresh():
    return {"branch": "widget-hourly", "upstream": "", "ahead": 2, "gone": False, "fail": None, "files": [
        {"path": "WeatherWidget/Provider.swift", "index": ".", "worktree": "M", "added": 12, "deleted": 3, "binary": False},
        {"path": "WeatherWidget/WidgetView.swift", "index": "A", "worktree": ".", "added": 18, "deleted": 0, "binary": False},
        {"path": "Sources/App/main.swift", "index": "M", "worktree": "M", "added": 2, "deleted": 1, "binary": False},
        {"path": "docs/hourly.md", "index": "?", "worktree": "?", "added": 0, "deleted": 0, "binary": False}],
        "stashes": [{"index": 0, "oid": "a" * 40, "message": "On main: alternate palette", "date": ago(days=2)}],
        "branches": [("widget-hourly", False), ("main", False), ("origin/main", True), ("origin/release-2.4", True)],
        "pr": None, "pr_fail": None}
GIT_W = git_write_fresh()


def git_pr_make(kind, branch, title="小组件：逐小时预报", draft=False):
    """A made-up pull request for the branch: being reviewed (a failed check, two open threads), ready, or set to merge."""
    pr = {"number": 128, "url": "https://github.com/example/weather/pull/128", "title": title, "state": "OPEN", "draft": draft,
          "base": "main", "head": branch, "mergeable": "MERGEABLE", "merge_state": "CLEAN", "review": "APPROVED", "checks": [], "threads": []}
    if kind == "new":
        pr.update(merge_state="BLOCKED", review="REVIEW_REQUIRED", checks=[
            {"name": "build (macos-15)", "state": "pending", "url": "https://github.com/example/weather/actions/runs/1"},
            {"name": "lint", "state": "pending", "url": "https://github.com/example/weather/actions/runs/2"}], checks_state="pending")
    elif kind in ("review", "auto"):
        pr.update(merge_state="BLOCKED", review="CHANGES_REQUESTED", auto_merge=kind == "auto", checks_state="failing", checks=[
            {"name": "build (macos-15)", "state": "pass", "url": "https://github.com/example/weather/actions/runs/1"},
            {"name": "unit tests", "state": "fail", "url": "https://github.com/example/weather/actions/runs/2"},
            {"name": "lint", "state": "pass", "url": "https://github.com/example/weather/actions/runs/3"},
            {"name": "preview deploy", "state": "skipped"}], threads=[
            {"path": "WeatherWidget/Provider.swift", "line": 42, "comments": [
                {"author": "reviewer-a", "body": "这里每次刷新都重新请求整天的预报，换成只取接下来 12 小时吧？", "url": "https://github.com/example/weather/pull/128#discussion_r1", "at": ago(hours=5)},
                {"author": "me", "body": "好，我改一下。", "url": "https://github.com/example/weather/pull/128#discussion_r2", "at": ago(hours=4)}]},
            {"path": "WeatherWidget/WidgetView.swift", "line": 17, "outdated": True, "comments": [
                {"author": "reviewer-b", "body": "降雨条的颜色在深色模式下对比度不够，用 `Theme.Hue.rain` 之类的 token，别写死 `#4A90E2`。", "url": "https://github.com/example/weather/pull/128#discussion_r3", "at": ago(hours=2)}]}])
    else:
        pr.update(checks_state="passing", checks=[
            {"name": "build (macos-15)", "state": "pass", "url": "https://github.com/example/weather/actions/runs/1"},
            {"name": "unit tests", "state": "pass", "url": "https://github.com/example/weather/actions/runs/2"},
            {"name": "lint", "state": "pass", "url": "https://github.com/example/weather/actions/runs/3"}])
    return pr


def git_pr(h, op, body):
    """POST git/pr (open one) and git/pr/merge on the made-up repository (MOCK_GIT_WRITE)."""
    w = GIT_W
    time.sleep(0.4)
    if w["fail"]:
        code, _ = w["fail"]
        w["fail"] = None
        return h.send_json({"error": "gh pr %s: %s" % ("create" if op == "pr" else "merge", code), "code": code}, 409)
    if op == "pr":
        if not w["upstream"] or w["ahead"]:
            return h.send_json({"error": "%s has commits that are not pushed" % w["branch"], "code": "git_not_pushed"}, 409)
        w["pr"] = git_pr_make("new", w["branch"], body.get("title") or w["branch"], bool(body.get("draft")))
    else:
        pr = w["pr"]
        if not pr: return h.send_json({"error": "no pull requests found for branch \"%s\"" % w["branch"], "code": "git_no_pr"}, 409)
        if body.get("auto_off"): pr["auto_merge"] = False
        elif body.get("auto"): pr["auto_merge"] = True
        elif pr["merge_state"] not in ("CLEAN", "UNSTABLE", "HAS_HOOKS"):
            return h.send_json({"error": "gh pr merge: X Pull request example/weather#128 is not mergeable: the base branch policy prohibits the merge.", "code": "git_failed"}, 409)
        else: pr["state"] = "MERGED"
    return h.send_json({"branch": w["branch"], "pr": w["pr"]})


def git_write_status(root):
    w = GIT_W
    head = MOCK_COMMITS[0] if w["ahead"] <= 2 else dict(MOCK_COMMITS[0], hash="e" * 40, short="eeeeeee", subject=w.get("last", MOCK_COMMITS[0]["subject"]))
    return {"is_repo": True, "root": root, "branch": w["branch"], "head": head, "upstream": w["upstream"], "ahead": w["ahead"],
            "behind": 0, "stashes": len(w["stashes"]), "commits": ([head] if head is not MOCK_COMMITS[0] else []) + MOCK_COMMITS[:29],
            "files": [dict(f) for f in w["files"]], **({"gone": True} if w["gone"] else {})}


def git_branches():
    return {"branches": [{"name": n, "remote": r, "current": n == GIT_W["branch"], "hash": "a1b2c3d",
                          "subject": MOCK_COMMITS[i % len(MOCK_COMMITS)]["subject"], "date": ago(hours=3 * i + 1)}
                         for i, (n, r) in enumerate(GIT_W["branches"])
                         if not (r and (n.split("/", 1)[1], False) in GIT_W["branches"])]}  # as the node: a remote one with a local one of its name is left out


def git_write(h, p, body):
    """POST git/{stage,commit,push,switch,stash} on the made-up repository (MOCK_GIT_WRITE)."""
    w, op = GIT_W, p.rsplit("/", 1)[-1]
    home, _ = mock_abs(p.split("/")[4], body.get("cwd", ""), "")
    root = home + "/" + MOCK_REPO
    time.sleep(0.4)
    if w["fail"]:
        code, files = w["fail"]
        w["fail"] = None
        words = {"git_conflict": "error: Your local changes to the following files would be overwritten by checkout:\n\t" + "\n\t".join(files) +
                                 "\nPlease commit your changes or stash them before you switch branches.\nAborting",
                 "git_push_rejected": " ! [rejected]        widget-hourly -> widget-hourly (fetch first)\nerror: failed to push some refs",
                 "git_hook_failed": "swiftlint: 2 violations in WeatherWidget/Provider.swift\n  12:5 Line Length Violation\n  30:1 Trailing Whitespace"}.get(code, code)
        return h.send_json({"error": "git %s: %s" % (op, words), "code": code, **({"files": files} if files else {})}, 409)
    out = {}
    if op == "stage":
        for f in w["files"]:
            if f["path"] not in body.get("paths", []): continue
            if body.get("unstage"):
                if f["index"] == "A": f.update(index="?", worktree="?")
                elif f["index"] not in (".", "?"): f.update(index=".", worktree="M")
            else:
                f.update(index="A" if f["index"] == "?" else "M", worktree=".")
    elif op == "commit":
        if not any(f["index"] not in (".", "?") for f in w["files"]):
            return h.send_json({"error": "nothing is staged", "code": "git_nothing_staged"}, 409)
        w["files"] = [dict(f, index=".") if f["worktree"] not in (".", "?") else f for f in w["files"] if f["worktree"] != "." or f["index"] in (".", "?")]
        w["ahead"] += 1
        w["last"] = body.get("message", "").split("\n")[0]
        out["commit"] = {"hash": "e" * 40, "short": "eeeeeee", "subject": w["last"], "author": "Me"}
    elif op == "push":
        if not w["upstream"]:
            if not body.get("set_upstream"): return h.send_json({"error": "no upstream", "code": "git_no_upstream"}, 409)
            w["upstream"] = "origin/" + w["branch"]
            w["branches"].append(("origin/" + w["branch"], True))
        w["ahead"], w["gone"] = 0, False
        out["output"] = "To github.com:example/weather.git\n*\trefs/heads/%s:refs/heads/%s\t[new branch]" % (w["branch"], w["branch"])
    elif op == "switch":
        name = body.get("branch", "")
        if body.get("create"):
            w["branches"].insert(0, (name, False))
            w["upstream"], w["ahead"] = "", 0
        elif ("origin/" + name, True) in w["branches"] and (name, False) not in w["branches"]:
            w["branches"].insert(0, (name, False))
            w["upstream"], w["ahead"] = "origin/" + name, 0
        else:
            w["upstream"], w["ahead"] = ("origin/" + name if ("origin/" + name, True) in w["branches"] else ""), 0
        w["branch"], w["gone"] = name, False
    elif op == "stash":
        o = body.get("op")
        if o == "push":
            if not w["files"]: return h.send_json({"error": "no local changes to save", "code": "git_no_stash"}, 409)
            msg = body.get("message") or ("WIP on %s" % w["branch"])
            w["stashes"] = [{"index": 0, "oid": hashlib.sha1((msg + str(time.time_ns())).encode()).hexdigest(), "message": "On %s: %s" % (w["branch"], msg), "date": ago(minutes=0)}] + [dict(s, index=s["index"] + 1) for s in w["stashes"]]
            w["files"] = [] if body.get("untracked") else [f for f in w["files"] if f["index"] == "?"]
        elif o in ("pop", "drop", "apply"):
            i = body.get("index", -1)
            if not isinstance(i, int) or i < 0 or i >= len(w["stashes"]) or body.get("oid") != w["stashes"][i]["oid"]:
                return h.send_json({"error": "Refresh and reselect the stash", "code": "git_stash_stale"}, 409)
            if o == "apply" or o == "pop":
                w["files"].append({"path": "Sources/App/Theme.swift", "index": ".", "worktree": "M", "added": 6, "deleted": 2, "binary": False})
            if o != "apply":
                w["stashes"] = [dict(s, index=k) for k, s in enumerate(x for j, x in enumerate(w["stashes"]) if j != i)]
        out["stashes"] = w["stashes"]
    return h.send_json({"status": git_write_status(root), **out})


def fs_changed(mid, dirs, git):
    """Tell the browsers watching `dirs` (absolute) or the Git status of their folder what changed (hub/fswatch.go)."""
    n = 0
    with FAULT_LOCK:
        targets = [(w["_send"], w) for ws in FS_WATCHES.values() for w in ws.values() if w.get("machine_id") == mid]
    for send, w in targets:
        hit = [d for d in dirs if d in (w.get("paths") or [])]
        git_hit = bool(git and w.get("git"))
        if hit or git_hit:
            send({"type": "fs_changed", "machine_id": mid, "cwd": w.get("cwd"), "dirs": hit, "git": git_hit})
            n += 1
    return n


def mock_files(p, q):
    """(json, status) for the files / Git endpoints, or None when p is not one of them."""
    parts = p.split("/")
    if not (p.startswith("/api/v1/machines/") and len(parts) >= 6): return None
    mid, what = parts[4], "/".join(parts[5:])
    if what not in ("file", "fs", "fs/find", "git/status", "git/diff", "git/show", "git/log", "git/branches", "git/pr") and not (what == "git/review" and GIT_REVIEW): return None
    if not machine_online(mid): return {"error": "%s: machine is offline" % mid}, 503
    arg = lambda k: (q.get(k) or [""])[0]
    if what == "fs/find":  # #2438: every file under cwd, shallow first (the node's walk / git ls-files)
        home, path = mock_abs(mid, "", arg("cwd"))
        rel = mock_rel(home, path)
        if rel is None or not (rel == "" or rel.endswith("/")): return {"error": "not a directory: %s" % path}, 502
        files = sorted((k[len(rel):] for k, v in MOCK_TREE.items() if k.startswith(rel) and not k.endswith("/")),
                       key=lambda f: (f.count("/"), f))
        return {"cwd": path, "files": files, "truncated": False, "source": "git"}, 200
    if what in ("file", "fs"):
        home, path = mock_abs(mid, arg("path"), arg("cwd"))
        rel = mock_rel(home, path)
        if rel is None: return {"error": "open %s: no such file or directory" % path}, 502
        is_dir = rel == "" or rel.endswith("/")
        if what == "fs":
            if not is_dir: return {"error": "readdir %s: not a directory" % path}, 502
            ents = [{"name": k[len(rel):].rstrip("/"), "dir": k.endswith("/"), "size": mock_size(MOCK_TREE[k]),
                     "mtime": ago(hours=i + 1)} for i, k in enumerate(mock_children(rel))]
            if FS_LIVE:
                for e in ents:
                    if rel.startswith(MOCK_REPO) and e["name"] in FS_IGNORED: e["ignored"] = True
            return {"path": path, "entries": ents, "truncated": False}, 200
        name = path.rsplit("/", 1)[-1]
        if is_dir:
            return {"path": path, "name": name, "size": 0, "mime": "", "is_dir": True, "truncated": False,
                    "entries": [k[len(rel):] for k in mock_children(rel)]}, 200
        v = MOCK_TREE[rel]
        if isinstance(v, tuple):
            return {"path": path, "name": name, "size": mock_size(v), "mime": v[0], "data": v[1], "is_dir": False, "truncated": False}, 200
        mime = "text/markdown" if name.endswith(".md") else "text/plain"
        return {"path": path, "name": name, "size": mock_size(v), "mime": mime, "text": v, "is_dir": False, "truncated": False}, 200
    home, cwd = mock_abs(mid, arg("cwd"), "")
    root = home + "/" + MOCK_REPO
    if not (cwd == root or cwd.startswith(root + "/")):
        if what == "git/review": return {"error": "not a Git repository", "code": "not_git"}, 409
        return ({"is_repo": False, "files": [], "commits": []}, 200) if what == "git/status" else ({"error": "not a git repository"}, 502)
    if what == "git/review":
        return mock_review.answer(q, root, MOCK_TREE, MOCK_REPO, MOCK_COMMITS, EDIT_OLD, EDIT_NEW)
    if what == "git/branches":
        return (git_branches(), 200) if os.environ.get("MOCK_GIT_WRITE") else ({"error": "not found"}, 404)
    if what == "git/pr":
        if not os.environ.get("MOCK_GIT_WRITE"): return {"error": "not found"}, 404
        time.sleep(0.3)
        if GIT_W["pr_fail"]:
            return {"error": {"no_gh": "gh is not installed on this machine", "not_signed_in": "gh is not signed in on this machine: run gh auth login"}.get(GIT_W["pr_fail"], GIT_W["pr_fail"]), "code": GIT_W["pr_fail"]}, 409
        return {"branch": GIT_W["branch"], "pr": GIT_W["pr"] if GIT_W["pr"] and GIT_W["pr"]["head"] == GIT_W["branch"] else None}, 200
    if what == "git/status":
        if os.environ.get("MOCK_GIT_WRITE"):
            return git_write_status(root), 200
        if os.environ.get("MOCK_GIT_PULL"):
            commits = MOCK_COMMITS[:30]
            if GIT_PULL_STATE["behind"] == 0:
                latest = dict(MOCK_COMMITS[0], hash="f" * 40, short="fffffff", subject="更新示例代码")
                commits = [latest] + commits[:29]
            files = [{"path": "Sources/App/main.swift", "index": ".", "worktree": "M", "added": 2, "deleted": 1}] if GIT_PULL_STATE["mode"] == "error" else []
            return {"is_repo": True, "root": root, "branch": "main", "head": commits[0], "upstream": "origin/main",
                    "ahead": 0, "behind": GIT_PULL_STATE["behind"], "stashes": 1, "commits": commits, "files": files}, 200
        return {"is_repo": True, "root": root, "branch": "main", "head": MOCK_COMMITS[0], "upstream": "origin/main",
                "ahead": 1 + FS_STATE["dirty"], "behind": FS_STATE["dirty"], "stashes": 1, "commits": MOCK_COMMITS[:30], "files": [
                    {"path": "Sources/App/main.swift", "index": "M", "worktree": "M", "added": 2, "deleted": 1, "binary": False},
                    {"path": "README.md", "index": ".", "worktree": "M", "added": 2, "deleted": 0, "binary": False},
                    {"path": "WeatherWidget/Provider.swift", "index": ".", "worktree": "M",
                     **diff_counts(MOCK_DIFFS["WeatherWidget/Provider.swift"]), "binary": False},
                    {"path": "WeatherWidget/WidgetView.swift", "index": "A", "worktree": ".",
                     **diff_counts(MOCK_DIFFS["WeatherWidget/WidgetView.swift"]), "binary": False},
                    {"path": "docs/icon.png", "index": "?", "worktree": "?", "added": 0, "deleted": 0, "binary": True}]
                + [{"path": rel, "index": ".", "worktree": "M", "added": 0, "deleted": 0, "binary": True} for rel in COMPARE_BLOBS]
                + [{"path": "Sources/App/Models/Forecast.swift", "index": ".", "worktree": "M", "added": 3, "deleted": 0, "binary": False}
                   for _ in range(min(FS_STATE["dirty"], 1))]}, 200
    if what == "git/diff":
        return {"path": arg("path"), "diff": MOCK_DIFFS.get(arg("path"), ""), "truncated": False}, 200
    if what == "git/log":
        skip, limit = int(arg("skip") or 0), int(arg("limit") or 50)
        return {"commits": MOCK_COMMITS[skip:skip + limit], "has_more": skip + limit < len(MOCK_COMMITS)}, 200
    c = next((c for c in MOCK_COMMITS if c["hash"] == arg("hash")), None)
    if not c: return {"error": "unknown revision"}, 502
    return {"commit": dict(c, body="Made-up commit for the mock hub."),
            "files": [{"path": "Sources/App/main.swift", "index": "M", "worktree": ".", "added": 2, "deleted": 1, "binary": False},
                      {"path": "README.md", "index": "M", "worktree": ".", "added": 2, "deleted": 0, "binary": False}],
            "diff": MOCK_DIFFS["Sources/App/main.swift"] + "\n" + MOCK_DIFFS["README.md"], "truncated": False}, 200
# --- end of Files & Git ---


# --- Files & Git on Android (docs/android/android.md "Files and Git in conversations"): a PDF in the tree, a tag in the history, the
# folders above the home (the browser can walk up to /), and with MOCK_FILES=1 the tree's files readable too (the
# big-file set answers …/file first). MOCK_TIME_OFFSET=+08:00: file and commit times carry the machine's own offset,
# as a real node sends them ("2026-10-31T13:58:40.205893083+08:00"), not Z.
def mock_pdf():
    """A small two-page PDF (made-up text, Helvetica, a coloured header and a chart), built here: no binary in the repo."""
    def esc(t): return t.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")
    pages = [("Weather widget guide", ["Small: the temperature now.", "Medium: the temperature and the next 6 hours of rain.",
                                       "Both refresh every hour from the shared cache."], [0.2, 0.4, 0.8, 0.6, 0.3, 0.1]),
             ("Release checklist", ["Screenshots in light and dark.", "Widget gallery text in both sizes.",
                                    "A TestFlight build for the internal group."], [0.9, 0.7, 0.5, 0.5, 0.2, 0.4])]
    objs = ["<< /Type /Catalog /Pages 2 0 R >>",
            "<< /Type /Pages /Kids [%s] /Count %d >>" % (" ".join("%d 0 R" % (4 + 2 * i) for i in range(len(pages))), len(pages)),
            "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"]
    for i, (title, lines, bars) in enumerate(pages):
        ops = ["0.18 0.44 0.91 rg 48 742 499 64 re f", "1 1 1 rg BT /F1 24 Tf 64 766 Td (%s) Tj ET" % esc(title),
               "0.1 0.1 0.12 rg BT /F1 13 Tf 64 700 Td 22 TL"] + ["(%s) Tj T*" % esc(l) for l in lines] + ["ET"]
        for j, h in enumerate(bars):
            ops.append("%.2f 0.62 0.86 rg %d 360 52 %d re f" % (0.25 + 0.1 * j, 72 + 76 * j, int(220 * h)))
        ops.append("0.4 0.4 0.45 rg BT /F1 10 Tf 64 330 Td (Rain chance, next 6 hours) Tj ET")
        ops.append("0.5 0.5 0.55 rg BT /F1 10 Tf 280 48 Td (%d / %d) Tj ET" % (i + 1, len(pages)))
        stream = "\n".join(ops)
        objs.append("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents %d 0 R >>" % (5 + 2 * i))
        objs.append("<< /Length %d >>\nstream\n%s\nendstream" % (len(stream), stream))
    out, offsets = b"%PDF-1.4\n", []
    for n, body in enumerate(objs, 1):
        offsets.append(len(out))
        out += ("%d 0 obj\n%s\nendobj\n" % (n, body)).encode()
    xref = len(out)
    out += ("xref\n0 %d\n0000000000 65535 f \n" % (len(objs) + 1)).encode()
    out += b"".join(("%010d 00000 n \n" % o).encode() for o in offsets)
    out += ("trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (len(objs) + 1, xref)).encode()
