BROWSER_JOBS = {}  # machine id -> {"kind": install|open, "at": started, "started": iso, "cancelled": bool}
# MOCK_HERDR_STOPPED=macbook,studio: those machines' classic herdr does not run (the Agents list's "herdr is not running"
# row with "Start", #1916); every other machine's does. MOCK_HERDR_START: how "Start" goes, "" (it comes up after 1.5 s),
# "fail" (502 with the node's reason), "slow" (6 s), "stale" (it comes up but GET keeps saying it does not, as a hub
# that only knew what node.info said). GET /mock/herdr: how many starts each machine was asked for; with
# ?stopped=<ids>&start=<how> it sets both (HerdrNoticeTests), and /mock/reset puts the environment's back.
def herdr_env():
    return {x.strip() for x in os.environ.get("MOCK_HERDR_STOPPED", "").split(",") if x.strip()}


HERDR_STOPPED = herdr_env()
HERDR_STARTS = {}
HERDR_MODE = {"start": os.environ.get("MOCK_HERDR_START", ""), "gen": 0}  # gen: a start begun before a reset is dropped


def herdr_now(mid):
    """GET /api/v1/machines/{mid}/herdr as the hub answers it."""
    return {"autostart": False, "running": mid not in HERDR_STOPPED, "known": True}


def herdr_start(mid):
    """POST /api/v1/machines/{mid}/herdr/start: (answer, status)."""
    HERDR_STARTS[mid] = HERDR_STARTS.get(mid, 0) + 1
    how, gen = HERDR_MODE["start"], HERDR_MODE["gen"]
    time.sleep(6 if how == "slow" else 1.5)
    if gen != HERDR_MODE["gen"]:  # the state was set anew meanwhile (the app that asked is gone): leave it be
        return {"error": "reset"}, 409
    if how == "fail":
        return {"error": "herdr server stopped right after starting: exit status 1"}, 502  # the node's words
    if how != "stale":
        HERDR_STOPPED.discard(mid)
    return {"autostart": False, "running": True, "known": True}, 200


BROWSER_INSTALL_STEPS = ["下载 ego lite", "校验签名和公证", "装进「应用程序」"]


def browser_state(state):
    analytics = os.environ.get("MOCK_BROWSER_ANALYTICS", "on")
    return {
        "missing": {"installed": False, "set_up": False, "ready": False, "note": "这台 Mac 上没有装 ego lite", "screen_sharing": True},
        "setup": {"installed": True, "version": "0.6.2", "set_up": False, "ready": False, "note": "ego lite 还没做完首次设置",
                  "analytics": "unknown", "screen_sharing": True},
        "ready": {"installed": True, "version": "0.6.2", "set_up": True, "imported": True, "analytics": analytics, "ready": True,
                  "screen_sharing": True},
    }[state]


def browser_of(machine_id, enabled):
    return {"enabled": enabled, **browser_state(MOCK_BROWSER if machine_id == "macbook" and MOCK_BROWSER in ("missing", "setup", "ready") else "missing")}


def browser_now(machine):
    """machine["browser"] as the node would say it now, the clock having moved an install or an open on."""
    b = machine["browser"]
    job = BROWSER_JOBS.get(machine["id"])
    if not b.get("enabled") or not job:
        return b
    t = (time.time() - job["at"]) / COMPUTER_STEP
    if job["kind"] == "install":
        if job.get("cancelled"):
            return {**b, "job": {"kind": "install", "state": "cancelled", "started": job["started"]}}
        if t < len(BROWSER_INSTALL_STEPS):
            return {**b, "job": {"kind": "install", "state": "running", "step": BROWSER_INSTALL_STEPS[int(t)], "started": job["started"]}}
        return {"enabled": True, **browser_state("setup"), "job": {"kind": "install", "state": "done", "started": job["started"]}}
    if t < 3:  # opened on the Mac: its setup goes on there
        return {"enabled": True, **browser_state("setup"), "job": {"kind": "open", "state": "done", "started": job["started"]}}
    return {"enabled": True, **browser_state("ready"), "job": {"kind": "open", "state": "done", "started": job["started"]}}


# Sign-ins in ego (#1304): the sites with cookies on MacBook, as browser.cookies.list gives them (no names, no values).
MOCK_COOKIE_SITES = {"github.com": [4, "2027-05-12T08:00:00Z"], "notion.so": [7, "2026-12-30T10:00:00Z"], "example.com": [2, None]}


def cookie_sites():
    return {"sites": [{"domain": d, "count": c, **({"expires": e} if e else {})} for d, (c, e) in sorted(MOCK_COOKIE_SITES.items())]}


COOKIES_FAILED = [False]  # MOCK_COOKIES_FAIL: the first read has failed


def cookie_call(method, q, body):
    """GET / POST / DELETE …/browser/cookies like the hub: the import's cookies are counted by site and dropped."""
    if method == "POST":
        cookies = json.loads(body or b"{}").get("cookies") or []
        if not cookies: return {"error": "没有要导入的 cookie"}, 400
        for c in cookies:
            site = ".".join(c.get("domain", "").lstrip(".").split(".")[-2:])
            n, e = MOCK_COOKIE_SITES.get(site, [0, None])
            exp = c.get("expires")
            MOCK_COOKIE_SITES[site] = [n + 1, datetime.fromtimestamp(exp, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ") if exp else e]
        return {**cookie_sites(), "imported": len(cookies)}, 200
    if method == "DELETE":
        gone = list(MOCK_COOKIE_SITES) if q.get("all", [""])[0] == "1" else [x for x in q.get("site", []) if x in MOCK_COOKIE_SITES]
        removed = sum(MOCK_COOKIE_SITES.pop(x)[0] for x in gone)
        return {**cookie_sites(), "removed": removed}, 200
    return cookie_sites(), 200


