# ---------- area: model defaults (#2455) ----------
# MOCK_MODEL_DEFAULTS=1: the main chat has a "Runtime" (cli / agentsdk, saved in its binding; "cli" is stored as none),
# GET /api/v1/machines/{mid}/launchers carries `default` (?purpose=, "New Agent"'s agent.new when absent), and the main
# conversation asked for the Agent SDK but runs on the CLI (runtime_fallback).
MODEL_DEFAULTS = os.environ.get("MOCK_MODEL_DEFAULTS") == "1"
MODEL_DEFAULTS_FALLBACK = "这台电脑没有 Node.js 22+"
_model_configuration_without_runtime = model_configuration


def model_configuration(include_uses=False):
    catalog = _model_configuration_without_runtime(include_uses)
    if not MODEL_DEFAULTS:
        return catalog
    for purpose in catalog["purposes"]:
        if purpose["id"] != "assistant":
            continue
        for binding in (purpose["override"], purpose["effective"]):
            if binding.get("runtime") == "cli":
                binding.pop("runtime")
        purpose["runtimes"] = ["cli", "agentsdk"]
        purpose["fields"] = purpose["fields"] + ["runtime"]
    return catalog


# The model profiles (GET /api/v1/model-profiles, docs/assistant/model-profiles.md) with the Agent presets of #2225: performance
# in use, as the templates are when first made.
MOCK_PRESETS = {"quick": {"launcher": "sonnetcc", "description": "Small, quick fixes"},
                "review": {"launcher": "claude", "model": "opus", "effort": "high", "description": "Code review and design"}}


def model_defaults_profiles(h, p):
    """GET /api/v1/model-profiles under MOCK_MODEL_DEFAULTS. False otherwise."""
    if not MODEL_DEFAULTS or p != "/api/v1/model-profiles":
        return False
    h.send_json({"revision": 1, "active": "performance", "events": [], "profiles": [
        {"id": "performance", "name": "Performance", "active": True, "changes": [], "tiers": MOCK_PRESETS},
        {"id": "economy", "name": "Economy", "changes": ["agent.new"], "tiers": {"quick": MOCK_PRESETS["quick"]}}]})
    return True


def model_defaults_launchers(h, p, q):
    """GET /api/v1/machines/{mid}/launchers with the purpose's "Default: …" (hub launcherDefault). False otherwise."""
    if not MODEL_DEFAULTS or not (p.startswith("/api/v1/machines/") and p.endswith("/launchers")):
        return False
    pid = q.get("purpose", ["agent.new"])[0]
    purpose = next((x for x in model_configuration()["purposes"] if x["id"] == pid), None)
    default = None
    if purpose and purpose["kind"] == "launcher":
        b = purpose["effective"]
        default = {"provider": b.get("provider", "").removeprefix("launcher."), "model": b.get("model", ""), "effort": b.get("effort", "")}
        if purpose.get("runtimes"):
            default["runtime"] = b.get("runtime") or "cli"
    out = {"launchers": launcher_health_list([{"name": "claude", "model": "opus"}, {"name": "sonnetcc", "model": "sonnet"},
                                              {"name": "codex", "model": "gpt-5.5", "agent": "codex", "agent_type": "codex"}]), "default": default}
    if pid == "agent.new":
        # "New agent"'s presets (#2225): the tiers of the profile in use whose launcher this machine starts
        out["tiers"] = [{"name": name, **tier} for name, tier in sorted(MOCK_PRESETS.items())]
        out["tiers_profile"] = {"id": "performance", "name": "Performance"}
    h.send_json(out)
    return True


if MODEL_DEFAULTS:
    for _s in ASSISTANT:
        if _s["session_id"] == ASSISTANT_CONFIG["main"]:
            _s["runtime_fallback"] = MODEL_DEFAULTS_FALLBACK
# ---------- end of area: model defaults ----------


# ---------- area: launcher health (#1643) ----------
# MOCK_LAUNCHER_HEALTH=1: "New Agent"'s launchers carry their health on the computer (docs/server/launcher-health.md): claude
# checked fine, work_gw blocked because new terminal tabs can't run it (not_in_terminal, #1642), team_gw blocked on its key.
# MOCK_LAUNCHER_HEALTH=default: Model Settings' New Agent default is work_gw too. Either way a start that runs work_gw fails
# after MOCK_START_SECONDS with the hub's coded sentence (start_error_code launcher_missing, where terminal), and a session
# that already failed so is listed (macbook/f1643000-0000-4000-8000-000000000001, for -openSession).
LAUNCHER_HEALTH = os.environ.get("MOCK_LAUNCHER_HEALTH", "")
LAUNCHER_HEALTH_FAILED = "f1643000-0000-4000-8000-000000000001"


def launcher_health_list(launchers):
    """The machine's launchers with health records (MOCK_LAUNCHER_HEALTH), else as they are."""
    if not LAUNCHER_HEALTH:
        return launchers
    out = [dict(l, health={"state": "ok", "checked_at": ago(minutes=12)}) if l["name"] == "claude" else dict(l) for l in launchers]
    out[1:1] = [
        {"name": "work_gw", "model": "glm-5.3", "health": {"state": "blocked", "kind": "not_in_terminal", "checked_at": ago(minutes=3),
                                                          "error": "bash: work_gw: command not found"}},
        {"name": "team_gw", "model": "sonnet", "health": {"state": "blocked", "kind": "auth", "checked_at": ago(minutes=40),
                                                         "error": 'API Error: 401 {"type":"error","error":{"type":"authentication_error","message":"invalid x-api-key"}}'}},
    ]
    return out


# MOCK_LANG=en|ja|zh-Hans (default zh-Hans, the hub's default): the language of the hub's sentence, as a hub answering a
# client in that language would write it, so a screenshot in English or Japanese is not checked against Chinese words.
LAUNCHER_HEALTH_LANG = os.environ.get("MOCK_LANG", "zh-Hans")


def launcher_health_refusal(machine_name):
    """What the hub says of a start the new tab's shell could not run work_gw in: its sentence, code and details."""
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import readiness_mock  # the hub's own catalogs (server/internal/i18n)
    args = {"launcher": "work_gw", "where": "terminal", "missing": "work_gw", "kind": "not_found", "pane_shell": "bash",
            "launcher_shell": "zsh", "rc_file": "~/.zshrc", "line": "bash: work_gw: command not found"}
    text = readiness_mock.t(LAUNCHER_HEALTH_LANG, "apierr-apierr.launcher_missing_terminal", machine=machine_name, **args)
    return {"start_error": text, "start_error_code": "launcher_missing", "start_error_args": args}


if LAUNCHER_HEALTH == "default":
    MODEL_BINDINGS["agent.new"] = {"revision": 1, "override": {"provider": "launcher.work_gw"}}
if LAUNCHER_HEALTH:
    SESSIONS.append(sess("macbook", LAUNCHER_HEALTH_FAILED, "整理天气数据", "/Users/me/code/weather-app", "offline", "offline",
                         "weather-app", 2, "agent-3", 3, 1, "", launcher="work_gw",
                         **launcher_health_refusal(next((m["name"] for m in MACHINES if m["id"] == "macbook"), "macbook"))))
# ---------- end of area: launcher health ----------


# ---------- HTTP ----------
class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def bad_network(self):
        """True when the hub is "down" (the connection is closed without an answer); otherwise waits out the delay."""
        if time.time() < NET["down_until"]:
            self.close_connection = True
            return True
        if NET["delay"] > 0:
            time.sleep(NET["delay"])
        return False

    def log_message(self, fmt, *a):
        LOG.write("%s %s\n" % (self.command, self.path)); LOG.flush()

    def send_json(self, obj, status=200, headers=None):
        global LOST_RECEIPT
        if self.command == "GET" and 200 <= status < 300:
            obj = stamp_managers(urlparse(self.path).path, obj)
        if 200 <= status < 300 and self.command in ("POST", "PUT", "PATCH", "DELETE") and self.path.startswith("/api/v1/"):
            with FAULT_LOCK:
                if LOST_RECEIPT:
                    LOST_RECEIPT = False
                    status, obj = 502, {"error": "操作回执丢失，请核对执行结果", "code": "lost_receipt",
                                        "delivered": "unknown", "retryable": False}
        if status >= 400 and isinstance(obj, dict):
            obj = dict(obj)
            obj.setdefault("code", {400: "invalid", 401: "unauthorized", 403: "forbidden", 404: "not_found",
                                    405: "method_not_allowed", 409: "conflict", 502: "upstream_error",
                                    503: "node_offline"}.get(status, "internal"))
        body = json.dumps(obj, ensure_ascii=False).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    def body(self):
        n = int(self.headers.get("Content-Length") or 0)
        return self.rfile.read(n) if n else b""

    def send_error(self, code, message=None, explain=None):
        self.close_connection = True
        self.send_json({"error": message or self.responses.get(code, ("请求失败",))[0]}, code)

    def token_refused(self):
        """MOCK_DEVICE_TOKEN=<token>: /api/ takes only that token, in Authorization or ?token=, and answers anything else
        401 invalid token as the hub does (#1498: the live screen's page got the app's token encoded twice).
        MOCK_PAIR_TOKEN=<jp_…>: a temporary pairing code as `personad hub pair` makes (docs/protocol/protocol.md "Temporary pairing"):
        it opens everything until traded once on POST /api/v1/auth/tokens, then for MOCK_PAIR_GRACE seconds (default 10,
        the hub's 2 minutes made short); the device tokens it was traded for keep working (#2766)."""
        u = urlparse(self.path)
        if MOCK_PAIR_TOKEN and u.path.startswith("/api/") and u.path != "/api/v1/health":
            got = self.headers.get("Authorization", "").removeprefix("Bearer ").strip() or (parse_qs(u.query).get("token") or [""])[0]
            ok = got in PAIR_DEVICE_TOKENS or (got == MOCK_PAIR_TOKEN and (PAIR_TRADED[0] is None or time.time() < PAIR_TRADED[0] + MOCK_PAIR_GRACE))
            if ok: return False
            print("mock: 401 %s %s (%s)" % (self.command, u.path, "pairing token" if got == MOCK_PAIR_TOKEN else "unknown token"), flush=True)
            self.send_json({"error": "invalid token"}, 401)
            return True
        want = os.environ.get("MOCK_DEVICE_TOKEN")
        if not want or not u.path.startswith("/api/"): return False
        got = self.headers.get("Authorization", "").removeprefix("Bearer ").strip() or (parse_qs(u.query).get("token") or [""])[0]
        if got == want: return False
        self.send_json({"error": "invalid token"}, 401)
        return True

    def do_GET(self):
        u = urlparse(self.path); p = u.path; q = parse_qs(u.query)
        HITS["GET " + p] = HITS.get("GET " + p, 0) + 1
        if self.token_refused(): return
        if preview_route and preview_route(self, "GET", p, q): return
        if p == "/api/v1/assistant/conversations/" + ASK1 + "/always":
            return self.send_json({"grants": ALWAYS_GRANTS})
        if recordings_route(self, "GET", p): return
        if custom_models_route(self, "GET", p, q): return
        if managers_route(self, "GET", p): return
        if _sent and _sent.route(self, "GET", p, q): return
        if providers_route(self, "GET", p, q, b""): return
        if MOCK_MESSAGING and p.startswith("/api/v1/messaging") and lark_messaging.route(self, "GET", p, q, b""): return
        if net_control(p, q): return self.send_json({"ok": True, **NET})
        if p == "/mock/fs-watch" and FS_LIVE:  # what the browsers asked to watch now
            with FAULT_LOCK:
                sets = [{k: v for k, v in m.items() if k != "_send"} for ws in FS_WATCHES.values() for m in ws.values()]
            return self.send_json({"watches": sets})
        if p == "/mock/fs-change" and FS_LIVE:  # dir (under the machine's home) gains the file `add`; git=1: the Git status moves
            mid = (q.get("machine") or ["macbook"])[0]
            home, path = mock_abs(mid, (q.get("dir") or [""])[0], "")
            add = (q.get("add") or [""])[0]
            if add:
                MOCK_TREE[mock_rel(home, path).rstrip("/") + "/" + add] = "added by the mock\n"
            git = (q.get("git") or [""])[0] == "1"
            if git: FS_STATE["dirty"] += 1
            return self.send_json({"ok": True, "sent": fs_changed(mid, [path] if add else [], git), "path": path})
        if p == "/mock/review" and GIT_REVIEW:
            return self.send_json(mock_review.control(q))
        if p == "/mock/git-write" and os.environ.get("MOCK_GIT_WRITE"):
            global GIT_W
            if q.get("reset"): GIT_W = git_write_fresh()
            if q.get("fail"): GIT_W["fail"] = (q["fail"][0], [f for f in (q.get("files") or [""])[0].split(",") if f])
            if q.get("pr"):
                kind = q["pr"][0]
                if kind != "none": GIT_W.update(upstream="origin/" + GIT_W["branch"], ahead=0)
                GIT_W["pr"] = None if kind == "none" else git_pr_make(kind, GIT_W["branch"])
            if "pr_fail" in q: GIT_W["pr_fail"] = q["pr_fail"][0] or None
            if q.get("gone"): GIT_W.update(upstream="origin/" + GIT_W["branch"], ahead=0, gone=True)
            return self.send_json({"branch": GIT_W["branch"], "ahead": GIT_W["ahead"], "files": len(GIT_W["files"])})
        if p == "/mock/git-pull" and os.environ.get("MOCK_GIT_PULL"):
            if "mode" in q:
                GIT_PULL_STATE.update(behind=28, mode=q["mode"][0], pulls=0)
            return self.send_json(GIT_PULL_STATE)
        if p == "/mock/screen-password":  # MOCK_SCREEN=fake: the Mac's password changed; who signed in how; what was typed
            if "p" in q: FAKE_SCREEN["password"] = q["p"][0]
            if "clear" in q: FAKE_SCREEN.update(typed="", clicks=[], clipboard="")
            if "clip" in q: fake_screen_clip(q["clip"][0])  # the Mac copied this
            if "slow" in q: FAKE_SCREEN["slow"] = float(q["slow"][0])
            if "down" in q:
                FAKE_SCREEN["down"] = q["down"][0] == "1"
                for conn in list(FAKE_SCREEN["conns"]) if FAKE_SCREEN["down"] else []:
                    try: conn["sock"].shutdown(socket.SHUT_RDWR)
                    except OSError: pass
            return self.send_json({"signins": FAKE_SCREEN["signins"], "typed": FAKE_SCREEN["typed"], "clicks": FAKE_SCREEN["clicks"],
                                   "pointer": FAKE_SCREEN["pointer"], "clipboard": FAKE_SCREEN["clipboard"], "frames": FAKE_SCREEN["frames"]})
        if p == "/mock/churn":
            CHURN["rounds"] = 0
            threading.Thread(target=churn, args=(int(q.get("n", ["20"])[0]), int(q.get("ms", ["300"])[0]),
                                                 int(q.get("steps", ["1"])[0]), q.get("final", ["0"])[0] == "1",
                                                 q.get("inbox", ["0"])[0] == "1", q.get("waiting", ["0"])[0] == "1",
                                                 q.get("real", ["0"])[0] == "1"), daemon=True).start()
            return self.send_json({"ok": True})
        if p == "/mock/churned": return self.send_json(CHURN)
        if p == "/mock/send-fail":
            SEND_FAIL["on"] = q.get("on", ["1"])[0] == "1"
            return self.send_json(SEND_FAIL)
        if p == "/mock/frames_label":
            FRAMES["label"] = q.get("name", [""])[0]
            return self.send_json({"ok": True})
        if p == "/mock/frames_glide_context":
            if "run_id" in q:
                FRAME_GLIDE_CONTEXT.clear()
                FRAME_GLIDE_CONTEXT.update(name=q.get("name", [""])[0], run_id=q["run_id"][0],
                                           warm_up=q.get("warm_up", ["0"])[0] == "1", action="glide",
                                           expected_iterations=int(q.get("expected_iterations", ["5"])[0]))
            return self.send_json(dict(FRAME_GLIDE_CONTEXT))
        if p == "/mock/frames":
            name = q.get("name", [None])[0]
            return self.send_json({"runs": [r for r in FRAMES["runs"] if name is None or r.get("test") == name]})
        if p == "/mock/persona-tier":
            set_persona_tier(q.get("tier", [""])[0])
            return self.send_json({"ok": True, "tier": PERSONA_TIER["tier"]})
        if p == "/mock/lark_churn":
            LARK_CHURN["rounds"] = 0
            threading.Thread(target=lark_churn, args=(q.get("feed", ["f3"])[0], int(q.get("n", ["16"])[0]), int(q.get("ms", ["500"])[0]),
                                                      q.get("new", ["0"])[0] == "1", q.get("inbox", ["0"])[0] == "1"), daemon=True).start()
            return self.send_json({"ok": True})
        if p == "/mock/lark_churned": return self.send_json(LARK_CHURN)
        if p == "/mock/truth": return self.send_json(truth())
        if p == "/mock/wire": return self.send_json(wire_state())
        if p == "/mock/sync/truth": return self.send_json(sync_truth(q.get("session", [""])[0]))
        if p == "/mock/bump": return self.send_json(bump(q.get("what", ["last"])[0], q.get("session", [None])[0]))
        if p == "/mock/mark": return self.send_json({"ok": True})  # a test's marker in the request log (explore)
        if p == "/mock/photo": return self.send_json(set_photo(q.get("on", ["1"])[0] == "1"))  # PhotoSaveTests' own fixture
        if p == "/mock/lark_send_delay": return self.send_json(set_lark_send_delay(q.get("s", [""])[0]))  # LarkSendTests
        if p == "/mock/agent_live" and AGENT_LIVE:  # an agent's reply streaming as Claude shows it (MOCK_AGENT_LIVE above)
            return self.send_json(agent_live(q.get("step", [""])[0], int(q.get("n", ["0"])[0])))
        if p == "/mock/narrate":  # #1966: words streamed before a tool call, recorded as thinking; ?step=start|finish
            args = (q.get("step", [""])[0], q.get("words", ["我先找一下负责的 Agent，再把任务交给它。"])[0], q.get("answer", ["已交给负责的 Agent。"])[0],
                    int(q.get("steps", ["8"])[0]), int(q.get("ms", ["250"])[0]), q.get("line", ["1"])[0] != "0")
            if args[0] == "start":  # streams for a few seconds: the test looks for the words meanwhile
                threading.Thread(target=narrate, args=args, daemon=True).start()
                return self.send_json({"ok": True})
            return self.send_json(narrate(*args))
        if p == "/mock/say":  # ChatFollowTests: a reply arrives in every open conversation (?text=…, ?user=… a message before it)
            # &steps=50&ms=80: the hub's own pace (a delta every 80 ms, node/assistant.go).
            # &history=mock-1.r1: the transcript's history token from now on, on pushes and pages alike (a branch was abandoned,
            # the file was rewritten: docs/protocol/protocol.md "Item continuity"); /mock/reset puts mock-1 back.
            if q.get("history", [""])[0]: HISTORY_NOW["token"] = q["history"][0]
            args = (SAY_PRESETS.get(q.get("preset", [""])[0]) or q.get("text", ["好了。"])[0], q["user"][0] if "user" in q else None, q.get("stream", ["0"])[0] == "1",
                    int(q.get("steps", ["10"])[0]), int(q.get("ms", ["300"])[0]), int(q.get("late", ["0"])[0]), q.get("drop", ["0"])[0] == "1")
            threading.Thread(target=say, args=args, daemon=True).start()
            return self.send_json({"ok": True})
        if MOCK_LARK and (p.startswith("/api/v1/lark/") or p == "/mock/lark") and fs_get(self, p, q): return  # area: feishu chat page
        if not p.startswith("/mock/") and self.bad_network(): return
        if p == "/api/v1/ws":
            return self.websocket()
        if plugins_route(self, p, None): return
        if voice_route(self, p, q): return
        if model_defaults_launchers(self, p, q): return  # area: model defaults
        if model_defaults_profiles(self, p): return  # area: model defaults
        if pins_route(self, p): return
        if chat_pins_route(self, p, parse_qs(urlparse(self.path).query)): return
        if history_route(self, p, parse_qs(urlparse(self.path).query)): return
        if p == "/mock/ports": return self.send_json({"connects": PORT_LOG})
        if p == "/mock/lark/uploads": return self.send_json(LARK_UPLOAD_REPLIES)  # #1035: what each attachment quoted
